    static String closestShutter(double seconds,List<String> choices){PhotoMath.checkedTime(seconds);String best=null;double distance=Double.POSITIVE_INFINITY;for(String choice:choices)try{double delta=Math.abs(Math.log(PhotoMath.seconds(choice)/seconds));if(delta<distance){distance=delta;best=choice;}}catch(IllegalArgumentException special){}if(best==null)throw new IllegalArgumentException("暂无可用的快门档位");return best;}
