        zonePanel=new FrameLayout(this);FrameLayout gray=new FrameLayout(this);android.graphics.drawable.GradientDrawable clip=new android.graphics.drawable.GradientDrawable();clip.setColor(android.graphics.Color.TRANSPARENT);clip.setCornerRadius(dp(7));gray.setBackground(clip);gray.setClipToOutline(true);gray.addView(scale,new FrameLayout.LayoutParams(-1,-1));android.graphics.drawable.GradientDrawable outline=new android.graphics.drawable.GradientDrawable();outline.setColor(android.graphics.Color.TRANSPARENT);outline.setCornerRadius(dp(8));outline.setStroke(dp(1),DEEP_OUTLINE);gray.setForeground(outline);zonePanel.addView(gray,new FrameLayout.LayoutParams(-1,zoneHeight()));liveMarker=new View(this){final android.graphics.Paint paint=new android.graphics.Paint(3);final android.graphics.Path path=new android.graphics.Path();@Override protected void onDraw(android.graphics.Canvas canvas){if(!showMarker)return;float x=getWidth()*markerFraction;path.reset();path.moveTo(x,zoneHeight());path.lineTo(x-dp(6),zoneHeight()+dp(10));path.lineTo(x+dp(6),zoneHeight()+dp(10));path.close();paint.setColor(DEEP_ACCENT);paint.setStrokeWidth(getResources().getDisplayMetrics().density*1.5f);paint.setStyle(markerZone<-.5||markerZone>10.5?android.graphics.Paint.Style.STROKE:android.graphics.Paint.Style.FILL);canvas.drawPath(path,paint);}};liveMarker.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);zonePanel.addView(liveMarker,new FrameLayout.LayoutParams(-1,-1));zonePanel.addOnLayoutChangeListener((v,l,t,right,b,ol,ot,or,ob)->{if(right-l!=or-ol)updateZoneMarkers();});LinearLayout.LayoutParams zoneSize=new LinearLayout.LayoutParams(-1,zoneHeight());zoneSize.bottomMargin=dp(12);panel.addView(zonePanel,zoneSize);
