    private void updatePlacementStatus(){if(zonePanel!=null)zonePanel.setVisibility(placedZone>=0||!pins.isEmpty()?View.VISIBLE:View.GONE);if(zoneChoice!=null)zoneChoice.setText("区域放置  "+(placedZone<0?"未启用":ZONE_NAMES[placedZone])+" ›");if(zoneSummary!=null){zoneSummary.setText(placedZone>=0?"区域 "+ZONE_NAMES[placedZone]+" · "+(placedZone>5?"+":"")+(placedZone-5)+"档":pins.isEmpty()?"":"已保留 "+pins.size()+" 个测光点");zoneSummary.setVisibility(placedZone>=0||!pins.isEmpty()?View.VISIBLE:View.GONE);}}
    private void updateZoneMarkers(){updatePlacementStatus();if(zonePanel==null)return;double live=sample+correction(),held=locked?heldSample+correction():Double.NaN;boolean visible=Double.isFinite(held)&&Double.isFinite(live)&&meterReading.usable(SystemClock.elapsedRealtime());if(visible){markerZone=MeterGeometry.relativeZone(live,held,placedZone);float target=(float)MeterGeometry.zoneFraction(markerZone);if(!showMarker){markerFraction=markerTarget=target;}else if(Math.abs(target-markerTarget)>.00001f){markerTarget=target;if(markerAnimation!=null)markerAnimation.cancel();markerAnimation=android.animation.ValueAnimator.ofFloat(markerFraction,target);markerAnimation.setDuration(android.animation.ValueAnimator.areAnimatorsEnabled()?120:0);markerAnimation.setInterpolator(new android.view.animation.LinearInterpolator());markerAnimation.addUpdateListener(a->{markerFraction=(float)a.getAnimatedValue();liveMarker.invalidate();});markerAnimation.start();}}else if(markerAnimation!=null)markerAnimation.cancel();showMarker=visible;int needed=zoneHeight()+((showMarker||!pins.isEmpty())?dp(14):0);if(zonePanel.getLayoutParams()!=null&&zonePanel.getLayoutParams().height!=needed){zonePanel.getLayoutParams().height=needed;zonePanel.requestLayout();}liveMarker.invalidate();StringBuilder ids=new StringBuilder();for(double[] pin:pins)ids.append((int)pin[3]).append(',');if(!drawnPinIds.equals(ids.toString())){for(TextView dot:pinDots)zonePanel.removeView(dot);pinDots.clear();drawnPinIds=ids.toString();for(double[] pin:pins){final int id=(int)pin[3];TextView dot=new TextView(this);dot.setText(String.valueOf(id));dot.setTextSize(8);dot.setTextColor(android.graphics.Color.BLACK);dot.setGravity(Gravity.CENTER);dot.setIncludeFontPadding(false);dot.setTypeface(android.graphics.Typeface.create("sans-serif-black",android.graphics.Typeface.NORMAL));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(android.graphics.Color.WHITE);bg.setStroke(dp(1),android.graphics.Color.BLACK);bg.setCornerRadius(dp(7));dot.setBackground(bg);dot.setFocusable(true);dot.setContentDescription("测光点 "+id+"，点按移除");dot.setOnClickListener(v->{for(int n=0;n<pins.size();n++)if((int)pins.get(n)[3]==id){pins.remove(n);break;}pointRequest++;zoneReadings.clear();for(double[] item:pins)zoneReadings.add(item[2]);zoneText.setText(pins.isEmpty()?"测光点已清除":pins.size()+"点反差 "+PhotoMath.decimal(Collections.max(zoneReadings)-Collections.min(zoneReadings))+"档");regionOverlay.invalidate();updateZoneMarkers();});zonePanel.addView(dot,new FrameLayout.LayoutParams(dp(14),dp(14)));pinDots.add(dot);}}
        double baseline=Double.isFinite(held)?held:live;for(int i=0;i<pinDots.size();i++){TextView dot=pinDots.get(i);boolean usable=Double.isFinite(baseline)&&zonePanel.getWidth()>0;dot.setVisibility(usable?View.VISIBLE:View.INVISIBLE);if(usable){FrameLayout.LayoutParams pos=(FrameLayout.LayoutParams)dot.getLayoutParams();pos.leftMargin=Math.round(zonePanel.getWidth()*(float)MeterGeometry.zoneFraction(MeterGeometry.relativeZone(pins.get(i)[2],baseline,placedZone)))-dp(7);pos.topMargin=zoneHeight()+dp(1);dot.setLayoutParams(pos);}}
    }
