    private boolean supportsRegions(){Integer max=characteristics==null?null:characteristics.get(CameraCharacteristics.CONTROL_MAX_REGIONS_AE);return max!=null&&max>0;}
    private void selectZone(int zone){keepStop=false;if(placedZone!=zone&&mode!=2&&!supportsRegions()){Toast.makeText(this,"设备不支持区域测光",1).show();return;}placedZone=placedZone==zone?-1:zone;zoneScale.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);if(placedZone>=0&&mode!=2){mode=2;modeButton.setText("测光模式  "+modes[mode]+" ›");applyRegion();}updateZoneScale();if(Double.isFinite(sample)||Double.isFinite(heldSample))display();}
    private boolean selectPoint(MotionEvent event,boolean pin){if(contentWidth<=0||contentHeight<=0||event.getX()<left||event.getY()<top||event.getX()>left+contentWidth||event.getY()>top+contentHeight)return false;if(!supportsRegions()){Toast.makeText(this,"设备不支持区域测光",0).show();return true;}pointX=(event.getX()-left)/contentWidth;pointY=(event.getY()-top)/contentHeight;mode=2;modeButton.setText("测光模式  "+modes[mode]+" ›");final int request=++pointRequest,sessionGeneration=generation;final float px=pointX,py=pointY;applyRegion();regionOverlay.invalidate();regionOverlay.setAlpha(0);regionOverlay.animate().alpha(1).setDuration(250).setInterpolator(new android.view.animation.AccelerateDecelerateInterpolator()).start();if(pin){preview.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);final long requested=SystemClock.elapsedRealtime();ui.postDelayed(()->{if(!resumed||!meterReading.usable(SystemClock.elapsedRealtime())||generation!=sessionGeneration||pointRequest!=request||sampleAt<requested||!Double.isFinite(sample)||SystemClock.elapsedRealtime()-sampleAt>2000)return;if(pins.size()==5)pins.remove(0);pins.add(new double[]{px,py,sample+correction(),nextPinId++});zoneReadings.clear();for(double[] item:pins)zoneReadings.add(item[2]);zoneText.setText(pins.size()+"点反差 "+PhotoMath.decimal(Collections.max(zoneReadings)-Collections.min(zoneReadings))+"档");regionOverlay.invalidate();updateZoneMarkers();preview.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);},900);}return true;}
