    private void close(){meterReading.reset();captureAt=highlightAt=0;keepStop=false;generation++;pointRequest++;pins.clear();builder=null;callback=null;opening=false;clearPlacement();zoneReadings.clear();locked=false;heldSample=Double.NaN;sample=Double.NaN;nextPinId=1;if(saveControl!=null)saveControl.setEnabled(false);if(markerAnimation!=null)markerAnimation.cancel();updateZoneMarkers();updateLockControl();if(session!=null){session.close();session=null;}if(camera!=null){camera.close();camera=null;}if(surface!=null){surface.release();surface=null;}}
